WITH
existing_import_location AS (
    SELECT location_id
    FROM locations
    WHERE lower(name) = lower('Choir Room at the Music Building')
    LIMIT 1
),
inserted_import_location AS (
    INSERT INTO locations (name, description, coordinates)
    SELECT
        'Choir Room at the Music Building',
        'Auto-created from UNT calendar event import.',
        ST_SetSRID(
            ST_MakePoint(-97.150127, 33.210622),
            4326
        )
    WHERE NOT EXISTS (
        SELECT 1 FROM existing_import_location
    )
    RETURNING location_id
),
resolved_location AS (
    SELECT location_id FROM existing_import_location
    UNION ALL
    SELECT location_id FROM inserted_import_location
    LIMIT 1
),
existing_event AS (
    SELECT e.event_id
    FROM events e
    JOIN event_details d ON d.event_id = e.event_id
    WHERE d.metadata ->> 'source_uid' = 'tag:localist.com,2008:EventInstance_52214431966147'
      AND COALESCE(d.metadata ->> 'source_recurrence_id', '') = ''
    LIMIT 1
),
updated_existing_event AS (
    UPDATE events
    SET
        title = 'Doctoral Recital: Maxim Kudaev, piano',
        description = 'Important Links and Information 

 

Program  

