WITH
existing_import_location AS (
    SELECT location_id
    FROM locations
    WHERE lower(name) = lower('Winspear Performance Hall at the Murchison Performing Arts Center')
    LIMIT 1
),
inserted_import_location AS (
    INSERT INTO locations (name, description, coordinates)
    SELECT
        'Winspear Performance Hall at the Murchison Performing Arts Center',
        'Auto-created from UNT calendar event import.',
        ST_SetSRID(
            ST_MakePoint(-97.155100, 33.207272),
            4326
        )
    WHERE NOT EXISTS (
        SELECT 1 FROM existing_import_location
    )
    RETURNING location_id
),
resolved_location AS (
    SELECT location_id FROM existing_import_location
    UNION ALL
    SELECT location_id FROM inserted_import_location
    LIMIT 1
),
existing_event AS (
    SELECT e.event_id
    FROM events e
    JOIN event_details d ON d.event_id = e.event_id
    WHERE d.metadata ->> 'source_uid' = 'tag:localist.com,2008:EventInstance_52214530973656'
      AND COALESCE(d.metadata ->> 'source_recurrence_id', '') = ''
    LIMIT 1
),
updated_existing_event AS (
    UPDATE events
    SET
        title = 'Concert Winds',
        description = 'Important Links and Information 

 

Program  

Please note, this program is subject to change. Final program will be available by the day of the performance. 

 

Livestream link below.',
        location_id = (SELECT location_id FROM resolved_location),
        start_date_time = TIMESTAMP '2026-11-02 19:30:00',
        end_date_time = TIMESTAMP '2026-11-02 20:30:00',
        event_type = 'Social & Entertainment',
        status = 'SCHEDULED'::event_status,
        updated_at = CURRENT_TIMESTAMP
    WHERE event_id IN (SELECT event_id FROM existing_event)
    RETURNING event_id
),
inserted_event AS (
    INSERT INTO events (
        title,
        description,
        location_id,
        start_date_time,
        end_date_time,
        event_type,
        status
    )
    SELECT
        'Concert Winds',
        'Important Links and Information 

 

Program  

Please note, this program is subject to change. Final program will be available by the day of the performance. 

 

Livestream link below.',
        (SELECT location_id FROM resolved_location),
        TIMESTAMP '2026-11-02 19:30:00',
