        'Social & Entertainment',
        'SCHEDULED'::event_status
    WHERE NOT EXISTS (SELECT 1 FROM existing_event)
    RETURNING event_id
),
resolved_event AS (
    SELECT event_id FROM inserted_event
    UNION ALL
    SELECT event_id FROM updated_existing_event
    LIMIT 1
),
upserted_details AS (
    INSERT INTO event_details (
        event_id,
        source_url,
        source_location_name,
        room_detail,
        metadata
    )
    SELECT
        (SELECT event_id FROM resolved_event),
        'https://calendar.unt.edu/event/concert-winds2',
        'Winspear Performance Hall at the Murchison Performing Arts Center',
        NULL,
        '{"all_day": false, "categories": ["Social & Entertainment"], "source_geo": {"latitude": 33.207272, "longitude": -97.1551}, "source_recurrence_id": "", "source_status": "SCHEDULED", "source_uid": "tag:localist.com,2008:EventInstance_52214530973656"}'::jsonb
    WHERE EXISTS (SELECT 1 FROM resolved_event)
    ON CONFLICT (event_id) DO UPDATE
    SET
        source_url = EXCLUDED.source_url,
